        if isinstance(val, (int, float)) and not isinstance(val, bool):
            return float(val) * 2.0
        elif isinstance(val, list):
            return [double_value(x) for x in val]
        elif isinstance(val, str):
            match = re.match(r'^[-+]?\d*\.?\d+$', val.strip())
            if match:
