import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data")
    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("JSON data must be a non-empty list")
    records = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each item must be a dictionary")
        if 'country' not in item or 'population' not in item:
            raise ValueError("Each dictionary must contain 'country' and 'population'")
        if not isinstance(item['country'], str):
            raise ValueError("Country must be a string")
        pop = item['population']
        if not isinstance(pop, (int, float)):
            raise ValueError("Population must be numeric")
        if pop < 0:
            raise ValueError("Population cannot be negative")
        records.append({"Country": item['country'], "Population": int(math.floor(pop)) if isinstance(pop, float) else pop})
    df = pd.DataFrame(records, columns=["Country", "Population"])
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except IOError:
        raise IOError("Cannot write file to the specified directory")
    return os.path.abspath(file_path), df

import json
import re
from collections import Counter

REPLACE_NONE = "None"

def task_func(json_str):
    data = json.loads(json_str)

    def clean(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is None:
                    continue
                new_dict[k] = clean(v)
            return new_dict
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                if item is None:
                    continue
                new_list.append(clean(item))
            return new_list
        elif isinstance(obj, str):
            return re.sub(r'[\w\.-]+@[\w\.-]+\.\w+', REPLACE_NONE, obj)
        else:
            return obj

    cleaned = clean(data)

    def flatten(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from flatten(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from flatten(item)
        else:
            yield obj

    value_counts = Counter(flatten(cleaned))

    return {"data": cleaned, "value_counts": value_counts}

